settings.custom_liquid:
{% if product.has_only_default_variant %}
{% if product.metafields.custom.variants != blank %}

<label class="non-form form__label">Variants:</label>

<div class="variant-product-container">

{% assign variants = product.metafields.custom.variants.value %}
{% for variant in variants %}
<div class="variant-product">
<a href="{{ variant.url }}">
<div class="variant-thumbnail">
<img src="{{ variant.featured_image | img_url: '400x' }}">
</div>
</a>
</div>
{% endfor %}
</div>
{% endif %}
{% endif %}

{% if product.metafields.custom.bundle != blank %}

<label class="non-form form__label">In This Bundle:</label>

<div class="bundle-product-container">

{% assign bundle = product.metafields.custom.bundle.value %}
{% for pin in bundle %}
<div class="bundle-product">
<a href="{{ pin.url }}">
<div class="bundle-thumbnail">
<img src="{{ pin.featured_image | img_url: '400x' }}">
</div>
</a>
</div>
{% endfor %}
</div>
{% endif %}
